// @hrbr/agents — Agent schemas, catalog data, and identity helpers.
import { Schema } from 'effect'
import {
  MCP_CLIENT_NAME_TO_AGENT_FAMILY,
  fingerprintMcpAgentFamily,
  parsedAgentHostname,
} from '@hrbr/core/agent'
import type { McpAgentFingerprint } from '@hrbr/core/agent'

export { MCP_CLIENT_NAME_TO_AGENT_FAMILY, fingerprintMcpAgentFamily, parsedAgentHostname }
export type { McpAgentFingerprint }

// ── Origin confidence ────────────────────────────────────────────────

export const OriginConfidence = Schema.Literals(['high', 'pid', 'none'])
export type OriginConfidence = typeof OriginConfidence.Type

// ── Agent schema (DB row + computed is_online) ───────────────────────

export const Agent = Schema.Struct({
  id: Schema.String,
  workspace_id: Schema.String,
  machine_id: Schema.String,
  agent_family: Schema.String,
  origin_confidence: OriginConfidence,
  origin_source: Schema.String,
  first_seen_at: Schema.String,
  last_seen_at: Schema.String,
  is_online: Schema.Boolean,
  display_name: Schema.NullOr(Schema.String),
  tags: Schema.String,
  metadata: Schema.String,
  created_by: Schema.String,
  created_at: Schema.String,
  updated_at: Schema.String,
})
export type Agent = typeof Agent.Type

// ── Request bodies ───────────────────────────────────────────────────

export const AnnounceAgentBody = Schema.Struct({
  workspace_id: Schema.String.check(Schema.isUUID()),
  machine_id: Schema.NonEmptyString,
  agent_family: Schema.NonEmptyString,
  origin_confidence: OriginConfidence,
  origin_source: Schema.String,
  metadata: Schema.optional(Schema.Record(Schema.String, Schema.Unknown)),
})
export type AnnounceAgentBody = typeof AnnounceAgentBody.Type

export const AgentIdBody = Schema.Struct({
  workspace_id: Schema.String.check(Schema.isUUID()),
  agent_id: Schema.String.check(Schema.isUUID()),
})
export type AgentIdBody = typeof AgentIdBody.Type

export const UpdateAgentBody = Schema.Struct({
  workspace_id: Schema.String.check(Schema.isUUID()),
  agent_id: Schema.String.check(Schema.isUUID()),
  display_name: Schema.optional(Schema.String),
  tags: Schema.optional(Schema.Array(Schema.String)),
  metadata: Schema.optional(Schema.Record(Schema.String, Schema.Unknown)),
})
export type UpdateAgentBody = typeof UpdateAgentBody.Type

// ── Agent catalog schemas ────────────────────────────────────────────

export const AgentIconStyle = Schema.Literals(['color', 'mono'])
export type AgentIconStyle = typeof AgentIconStyle.Type

export const AgentIconSpec = Schema.Struct({
  path: Schema.String,
  darkPath: Schema.optional(Schema.String),
  style: AgentIconStyle,
})
export type AgentIconSpec = typeof AgentIconSpec.Type

export const AgentCatalogKind = Schema.Literals(['local', 'mcp'])
export type AgentCatalogKind = typeof AgentCatalogKind.Type

export const AgentInstallInstructionKind = Schema.Literals(['handoff', 'mcp-shell', 'markdown'])
export type AgentInstallInstructionKind = typeof AgentInstallInstructionKind.Type

export const AgentInstallInstruction = Schema.Struct({
  id: Schema.String,
  label: Schema.String,
  kind: AgentInstallInstructionKind,
  command: Schema.optional(Schema.String),
  next: Schema.optional(Schema.String),
  instructions: Schema.optional(Schema.String),
})
export type AgentInstallInstruction = typeof AgentInstallInstruction.Type

export const AgentCatalogItem = Schema.Struct({
  slug: Schema.String,
  label: Schema.String,
  kind: AgentCatalogKind,
  icon: AgentIconSpec,
  iconPath: Schema.String,
  iconPathDark: Schema.String,
  envVars: Schema.Array(Schema.Struct({ name: Schema.String })),
  command: Schema.optional(Schema.String),
  description: Schema.optional(Schema.String),
  aliases: Schema.optional(Schema.Array(Schema.String)),
  installInstructions: Schema.optional(Schema.Array(AgentInstallInstruction)),
})
export type AgentCatalogItem = typeof AgentCatalogItem.Type

export const AgentConnectionStatus = Schema.Literals(['connected', 'disconnected'])
export type AgentConnectionStatus = typeof AgentConnectionStatus.Type

export const AgentInfo = Schema.Struct({
  id: Schema.String,
  family: Schema.String,
  alias: Schema.String,
  label: Schema.String,
  icon: AgentIconSpec,
  status: AgentConnectionStatus,
  last_seen_at: Schema.String,
  origin_confidence: OriginConfidence,
  hostname: Schema.optional(Schema.String),
})
export type AgentInfo = typeof AgentInfo.Type

// ── Install guide schemas ────────────────────────────────────────────

export const InstallGuideTab = Schema.Struct({
  id: Schema.String,
  label: Schema.String,
  instructions: Schema.String,
})
export type InstallGuideTab = typeof InstallGuideTab.Type

export const InstallAgentGuide = Schema.Struct({
  id: Schema.String,
  name: Schema.String,
  icon: Schema.String,
  image_url: Schema.String,
  tabs: Schema.Array(InstallGuideTab),
})
export type InstallAgentGuide = typeof InstallAgentGuide.Type

export const InstallGuideResponse = Schema.Struct({
  workflow: Schema.NullOr(Schema.String),
  agents: Schema.Array(InstallAgentGuide),
})
export type InstallGuideResponse = typeof InstallGuideResponse.Type

// ── Icon helpers ─────────────────────────────────────────────────────

function icon(name: string, ext = 'svg'): string {
  return `/agents/${name}.${ext}`
}

function iconDark(name: string, hasDark: boolean): string {
  return hasDark ? `/agents/${name}-white.svg` : `/agents/${name}.svg`
}

function withIcon(path: string, darkPath: string, style: AgentIconStyle = 'color'): AgentIconSpec {
  return { path, darkPath, style }
}

function catalogItem(args: {
  readonly slug: string
  readonly label: string
  readonly kind: AgentCatalogKind
  readonly icon: AgentIconSpec
  readonly envVars?: ReadonlyArray<{ readonly name: string }> | undefined
  readonly command?: string | undefined
  readonly description?: string | undefined
  readonly aliases?: ReadonlyArray<string> | undefined
  readonly installInstructions?: ReadonlyArray<AgentInstallInstruction> | undefined
}): AgentCatalogItem {
  return {
    slug: args.slug,
    label: args.label,
    kind: args.kind,
    icon: args.icon,
    iconPath: args.icon.path,
    iconPathDark: args.icon.darkPath ?? args.icon.path,
    envVars: [...(args.envVars ?? [])],
    ...(args.command ? { command: args.command } : {}),
    ...(args.description ? { description: args.description } : {}),
    ...(args.aliases ? { aliases: [...args.aliases] } : {}),
    ...(args.installInstructions ? { installInstructions: [...args.installInstructions] } : {}),
  }
}

const HANDOFF_INSTALL: AgentInstallInstruction = {
  id: 'handoff',
  label: 'Direct handoff',
  kind: 'handoff',
}

function mcpShellInstall(command: string, next: string): AgentInstallInstruction {
  return { id: 'mcp', label: 'MCP', kind: 'mcp-shell', command, next }
}

function markdownInstall(instructions: string): AgentInstallInstruction {
  return { id: 'mcp', label: 'MCP', kind: 'markdown', instructions }
}

function localInstallInstructions(
  command: string,
  next?: string
): ReadonlyArray<AgentInstallInstruction> {
  return [
    HANDOFF_INSTALL,
    mcpShellInstall(
      `${command} mcp add harbor {{mcpUrl}}`,
      next ?? `Restart ${command} and authorize Harbor for this workspace.`
    ),
  ]
}

