// ── Lookup helpers ───────────────────────────────────────────────────

const slugIndex = new Map<string, AgentCatalogItem>(
  AGENT_CATALOG.map((agent) => [agent.slug, agent])
)
const aliasIndex = new Map<string, AgentCatalogItem>(
  AGENT_CATALOG.flatMap((agent) => (agent.aliases ?? []).map((alias) => [alias, agent] as const))
)

export function getAgentCatalogItem(slug: string): AgentCatalogItem | undefined {
  return slugIndex.get(slug) ?? aliasIndex.get(slug)
}

export function canonicalAgentFamily(slug: string): string {
  return getAgentCatalogItem(slug)?.slug ?? slug
}

export function agentIconSpec(slugOrItem: string | AgentCatalogItem): AgentIconSpec | undefined {
  const entry = typeof slugOrItem === 'string' ? getAgentCatalogItem(slugOrItem) : slugOrItem
  return entry?.icon
}

export function getAgentIcon(slug: string, isDark = false): string | undefined {
  const iconSpec = agentIconSpec(slug)
  if (!iconSpec) return undefined
  return isDark ? (iconSpec.darkPath ?? iconSpec.path) : iconSpec.path
}

// ── Install guide helpers ────────────────────────────────────────────

export type InstallGuideMode = 'handoff' | 'mcp'

export interface BuildInstallGuideOptions {
  /** Curated workflow-backed skill id used by `hrbr skills get <id>`. */
  readonly workflow?: string | undefined
  /** Human-readable workflow name shown in agent handoff instructions. */
  readonly workflowName?: string | undefined
  readonly workspaceSlug?: string | undefined
  readonly dashboardUrl?: string | undefined
  readonly mcpUrl?: string | undefined
  readonly imageBaseUrl?: string | undefined
  /**
   * Setup paths to include in the response. Defaults to both handoff and
   * mcp. Pass `["handoff"]` to drop every MCP-only agent and every MCP
   * install instruction (used by the install page after ENG-601).
   */
  readonly modes?: ReadonlyArray<InstallGuideMode> | undefined
}

function installInstructionMode(instruction: AgentInstallInstruction): InstallGuideMode {
  return instruction.kind === 'handoff' ? 'handoff' : 'mcp'
}

const DEFAULT_DASHBOARD_URL = 'https://tryharbor.ai'
function trimTrailingSlash(value: string): string {
  return value.replace(/\/+$/, '')
}

function buildPublicUrl(pathOrUrl: string, baseUrl: string): string {
  if (/^https?:\/\//.test(pathOrUrl)) return pathOrUrl
  return `${trimTrailingSlash(baseUrl)}${pathOrUrl.startsWith('/') ? pathOrUrl : `/${pathOrUrl}`}`
}

function buildSkillUrl(args: {
  readonly dashboardUrl: string
  readonly workspaceSlug?: string | undefined
}): string {
  const base = buildPublicUrl('/skill.md', args.dashboardUrl)
  return args.workspaceSlug ? `${base}?ws=${encodeURIComponent(args.workspaceSlug)}` : base
}

function shellQuote(value: string): string {
  return `'${value.replaceAll("'", `'\\''`)}'`
}

type HandoffInstructionKey = 'default' | 'workflow'

type HandoffInstructionContext = {
  readonly skillUrl: string
  readonly workflowId?: string | undefined
  readonly workflowName?: string | undefined
}

const HANDOFF_PROMPTS: Record<HandoffInstructionKey, (ctx: HandoffInstructionContext) => string> = {
  default: () =>
    `curl https://tryharbor.ai/skill.md and read the downloaded text before taking any setup steps. Then help me set up Harbor: install it, verify complete login and workspace, show me any configured Harbor plugins, and explain what we can do.`,
  workflow: (ctx) => {
    const workflowId = ctx.workflowId?.trim()
    if (!workflowId) return HANDOFF_PROMPTS.default(ctx)
    const workflowName = ctx.workflowName?.trim()
    const workflowLabel = workflowName ? `the "${workflowName}" workflow` : 'this workflow'
    return `Read ${ctx.skillUrl}. Trigger Harbor auth/login yourself, then run \`hrbr skills get ${shellQuote(workflowId)}\` to fetch and execute ${workflowLabel}.`
  },
}

function resolveHandoffInstructionKey(ctx: HandoffInstructionContext): HandoffInstructionKey {
  return ctx.workflowId?.trim() ? 'workflow' : 'default'
}

function handoffInstructions(agentName: string, ctx: HandoffInstructionContext): string {
  const instructionKey = resolveHandoffInstructionKey(ctx)
  const handoffPrompt = HANDOFF_PROMPTS[instructionKey](ctx)
  return `1. Copy this prompt into ${agentName}:

\`\`\`text
${handoffPrompt}
\`\`\`

2. Let the agent follow the Harbor skill. It will ask you for any command, browser action, or confirmation it needs.`
}

function workflowMcpFollowup(ctx: HandoffInstructionContext): string | null {
  const workflowId = ctx.workflowId?.trim()
  if (!workflowId) return null
  const workflowName = ctx.workflowName?.trim()
  const workflowLabel = workflowName ? `the "${workflowName}" workflow` : 'this workflow'
  const prompt = `Call the Harbor MCP workflow tool with { "action": "get", "workflow_id": ${JSON.stringify(workflowId)} } to fetch ${workflowLabel}'s instructions, then execute those instructions step by step for me.`
  return `After Harbor MCP is connected, copy this prompt into the agent:

\`\`\`text
${prompt}
\`\`\``
}

function mcpShellInstructions(
  command: string,
  next: string,
  ctx: HandoffInstructionContext
): string {
  const followup = workflowMcpFollowup(ctx)
  return `1. Run the following command in your shell:

\`\`\`bash
${command}
\`\`\`

2. ${next}${followup ? `\n\n3. ${followup}` : ''}`
}

function renderInstallInstruction(
  instruction: AgentInstallInstruction,
  ctx: {
    readonly agentName: string
    readonly skillUrl: string
    readonly mcpUrl?: string | undefined
    readonly workflowId?: string | undefined
    readonly workflowName?: string | undefined
  }
): InstallGuideTab | null {
  if (instruction.kind === 'handoff') {
    return {
      id: instruction.id,
      label: instruction.label,
      instructions: handoffInstructions(ctx.agentName, {
        skillUrl: ctx.skillUrl,
        workflowId: ctx.workflowId,
        workflowName: ctx.workflowName,
      }),
    }
  }
  if (instruction.kind === 'mcp-shell' && instruction.command && instruction.next) {
    if (!ctx.mcpUrl) return null
    return {
      id: instruction.id,
      label: instruction.label,
      instructions: mcpShellInstructions(
        instruction.command.replaceAll('{{mcpUrl}}', ctx.mcpUrl),
        instruction.next.replaceAll('{{mcpUrl}}', ctx.mcpUrl),
        { skillUrl: ctx.skillUrl, workflowId: ctx.workflowId, workflowName: ctx.workflowName }
      ),
    }
  }
  if (instruction.kind === 'markdown' && instruction.instructions) {
    if (!ctx.mcpUrl) return null
    return {
      id: instruction.id,
      label: instruction.label,
      instructions: (() => {
        const base = instruction.instructions
          .replaceAll('{{mcpUrl}}', ctx.mcpUrl)
          .replaceAll('{{skillUrl}}', ctx.skillUrl)
        const followup = workflowMcpFollowup({
          skillUrl: ctx.skillUrl,
          workflowId: ctx.workflowId,
          workflowName: ctx.workflowName,
        })
        return followup ? `${base}\n\n3. ${followup}` : base
      })(),
    }
  }
  return null
}

export function buildInstallGuide(options: BuildInstallGuideOptions = {}): InstallGuideResponse {
  const dashboardUrl = options.dashboardUrl ?? DEFAULT_DASHBOARD_URL
  const mcpUrl = options.mcpUrl?.trim() || undefined
  const imageBaseUrl = options.imageBaseUrl ?? dashboardUrl
  const skillUrl = buildSkillUrl({ dashboardUrl, workspaceSlug: options.workspaceSlug })
  const enabledModes = new Set<InstallGuideMode>(options.modes ?? ['handoff', 'mcp'])
  const includeMcp = enabledModes.has('mcp')

  const agents = AGENT_CATALOG.flatMap((agent): InstallAgentGuide[] => {
    if (!includeMcp && agent.kind === 'mcp') return []
    const tabs = (agent.installInstructions ?? [])
      .filter((instruction) => enabledModes.has(installInstructionMode(instruction)))
      .map((instruction) =>
        renderInstallInstruction(instruction, {
          agentName: agent.label,
          skillUrl,
          mcpUrl,
          workflowId: options.workflow,
          workflowName: options.workflowName,
        })
      )
      .filter((tab): tab is InstallGuideTab => tab !== null)
    if (tabs.length === 0) return []
    return [
      {
        id: agent.slug,
        name: agent.label,
        icon: agent.slug,
        image_url: buildPublicUrl(agent.icon.path, imageBaseUrl),
        tabs,
      },
    ]
  })

  return {
    workflow: options.workflow ?? null,
    agents,
  }
}

// ── Alias helpers ────────────────────────────────────────────────────

/**
 * Build a friendly alias for an agent identified by `(machine_id, agent_family)`.
 * Used when `display_name` is unset. Examples:
 *   formatAgentAlias("pi", "hyperion")   ──▶ "Pi on hyperion"
 *   formatAgentAlias("codex", null)      ──▶ "Codex"
 *   formatAgentAlias("unknown", "box")   ──▶ "unknown on box"
 */
export function formatAgentAlias(agentFamily: string, hostname: string | null | undefined): string {
  const label = getAgentCatalogItem(agentFamily)?.label ?? agentFamily
  const host = hostname?.trim()
  return host && host.length > 0 ? `${label} on ${host}` : label
}

/**
 * Resolve the user-facing alias for an agent. Prefers user-edited
 * `display_name`, then computes one from `(agent_family, hostname)`.
 */
export function resolveAgentAlias(
  agent: Pick<Agent, 'agent_family' | 'display_name' | 'metadata'>
): string {
  const explicit = agent.display_name?.trim()
  if (explicit) return explicit
  return formatAgentAlias(agent.agent_family, parsedAgentHostname(agent.metadata))
}
