export interface McpAgentFingerprint {
  readonly family: string
  readonly clientLabel: string | null
  readonly confidence: 'high' | 'medium' | 'low'
  readonly source: 'client_info' | 'pattern' | 'fallback'
}

export const MCP_CLIENT_NAME_TO_AGENT_FAMILY: Readonly<Record<string, string>> = {
  'claude-code': 'claude-code',
  'claude-ai': 'claude-ai',
  ChatGPT: 'chatgpt',
  Codex: 'codex',
  'codex-mcp-client': 'codex',
  'cursor-vscode': 'cursor',
  'Visual-Studio-Code': 'copilot',
  'JetBrains Client': 'copilot',
  'IntelliJ IDEA': 'copilot',
  PyCharm: 'copilot',
  'mcp-inspector': 'mcp-local',
  'gemini-cli-mcp-client': 'gemini',
  'Kilo Code': 'opencode',
  'Kiro CLI': 'mcp-local',
  'Pi CLI': 'pi',
  'Pi Coding Agent': 'pi',
  Zed: 'mcp-local',
  zed: 'mcp-local',
  'qwen-code': 'mcp-local',
  'qwen-cli-mcp-client': 'mcp-local',
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null
}

export function parsedAgentHostname(metadataJson: string | null | undefined): string | null {
  if (!metadataJson) return null
  try {
    const parsed = asRecord(JSON.parse(metadataJson))
    const host = parsed?.hostname
    if (typeof host !== 'string') return null
    const trimmed = host.trim()
    return trimmed.length > 0 ? trimmed : null
  } catch {
    return null
  }
}

export function fingerprintMcpAgentFamily(
  rawClientName: string | null | undefined,
  options?: { readonly fallbackFamily?: string | undefined }
): McpAgentFingerprint {
  const clientLabel =
    rawClientName?.trim() && rawClientName.trim() !== '_default' ? rawClientName.trim() : null
  const normalized = clientLabel?.toLowerCase() ?? ''
  const fallbackFamily = options?.fallbackFamily ?? 'mcp-remote'

  if (clientLabel && MCP_CLIENT_NAME_TO_AGENT_FAMILY[clientLabel]) {
    return {
      family: MCP_CLIENT_NAME_TO_AGENT_FAMILY[clientLabel]!,
      clientLabel,
      confidence: 'high',
      source: 'client_info',
    }
  }

  if (clientLabel?.startsWith('qwen-cli-mcp-client')) {
    return { family: 'mcp-local', clientLabel, confidence: 'high', source: 'client_info' }
  }

  if (!normalized) {
    return { family: fallbackFamily, clientLabel: null, confidence: 'low', source: 'fallback' }
  }

  if (
    normalized.includes('claude code') ||
    normalized.includes('claude-code') ||
    normalized === 'claudecode'
  ) {
    return { family: 'claude-code', clientLabel, confidence: 'medium', source: 'pattern' }
  }
  if (
    /(^|[^a-z])codex([^a-z]|$)/.test(normalized) ||
    normalized.includes('openai-codex') ||
    normalized.includes('codex-cli') ||
    normalized.includes('codex desktop')
  ) {
    return { family: 'codex', clientLabel, confidence: 'medium', source: 'pattern' }
  }

  if (/(^|[^a-z])claude([^a-z]|$)/.test(normalized) || normalized.includes('anthropic')) {
    return { family: 'claude-ai', clientLabel, confidence: 'medium', source: 'pattern' }
  }

  if (
    normalized.includes('chatgpt') ||
    normalized.includes('openai') ||
    normalized === 'gpt' ||
    normalized.startsWith('gpt-')
  ) {
    return { family: 'chatgpt', clientLabel, confidence: 'medium', source: 'pattern' }
  }

  if (normalized.includes('cursor'))
    return { family: 'cursor', clientLabel, confidence: 'medium', source: 'pattern' }
  if (normalized.includes('gemini'))
    return { family: 'gemini', clientLabel, confidence: 'medium', source: 'pattern' }
  if (
    normalized.includes('opencode') ||
    normalized.includes('kilo code') ||
    normalized.includes('kilocode')
  ) {
    return { family: 'opencode', clientLabel, confidence: 'medium', source: 'pattern' }
  }
  if (normalized.includes('pi coding') || normalized === 'pi' || normalized.includes('pi cli')) {
    return { family: 'pi', clientLabel, confidence: 'medium', source: 'pattern' }
  }
  if (normalized.includes('openclaw'))
    return { family: 'openclaw', clientLabel, confidence: 'medium', source: 'pattern' }
  if (
    normalized.includes('copilot') ||
    normalized.includes('jetbrains') ||
    normalized.includes('intellij') ||
    normalized.includes('pycharm')
  ) {
    return { family: 'copilot', clientLabel, confidence: 'medium', source: 'pattern' }
  }
  if (normalized.includes('slate'))
    return { family: 'slate', clientLabel, confidence: 'medium', source: 'pattern' }

  if (
    normalized.includes('mcp inspector') ||
    normalized.includes('mcp-inspector') ||
    normalized === 'inspector' ||
    normalized.includes('goose') ||
    normalized.includes('mcpjam') ||
    normalized.includes('continue') ||
    normalized.includes('vscode') ||
    normalized.includes('visual studio')
  ) {
    return { family: 'mcp-local', clientLabel, confidence: 'medium', source: 'pattern' }
  }

  return { family: fallbackFamily, clientLabel, confidence: 'low', source: 'fallback' }
}
